local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[2986] = { title = "Call of Water", description = "Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.", objectives = "Find Islen Waterseer in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2987] = { title = "Gordunni Cobalt", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!", objectives = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2988] = { title = "Witherbark Cages", description = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.", objectives = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2989] = { title = "The Altar of Zul", description = "Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child. ", objectives = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2990] = { title = "Thadius Grimshade", description = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, $N.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.", objectives = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2991] = { title = "Nekrum's Medallion", description = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.", objectives = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2992] = { title = "The Divination", description = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.", objectives = "Wait until Grimshade performs the ritual of divination.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2993] = { title = "Return to the Hinterlands", description = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, $N.", objectives = "Speak with Gryphon Master Talonaxe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2994] = { title = "Saving Sharpbeak", description = "We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!", objectives = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2995] = { title = "Lines of Communication", description = "The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.\n\nWe don't need the Highvale building alliances with others, $N.\n\nDestroy the Highvale documents.  We need to burn their lines of communication... literally.", objectives = "Oran Snakewrithe in Undercity wants you to travel to the Hinterlands and burn the Highvale Records, Highvale Report, and Highvale Notes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2996] = { title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.", objectives = "Speak to Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2997] = { title = "Tome of Divinity", description = "Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, $N.", objectives = "Speak to Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2998] = { title = "Tome of Divinity", description = "Greetings, $Gbrother:sister;. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.", objectives = "Speak to Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2999] = { title = "Tome of Divinity", description = "Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.", objectives = "Speak to Tiza Battleforge in Ironforge", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3000] = { title = "Tome of Divinity", description = "Hello, $N. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.", objectives = "Speak to Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3001] = { title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.", objectives = "Find Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3002] = { title = "The Gordunni Orb", description = "Although I know my enemy well, I am a warrior, $N. I cannot begin to tell you what this orb is capable of.\n\nI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him. ", objectives = "Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3022] = { title = "Handle With Care", description = "$N, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.", objectives = "Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3042] = { title = "Troll Temper", description = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can!  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck.", objectives = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3062] = { title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", objectives = "Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3063] = { title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. $N, get my revenge. ", objectives = "Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3065] = { title = "Simple Tablet", description = "Ah, while you were gone a parchment came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", objectives = "Read the Simple Tablet and speak to Frang in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3082] = { title = "Etched Tablet", description = "Ah, while you were gone a tablet came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.", objectives = "Speak to Jen'shan in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3083] = { title = "Encrypted Tablet", description = "Ah, while you were gone a tablet came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", objectives = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3084] = { title = "Rune-Inscribed Tablet", description = "Ah, while you were gone a tablet came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", objectives = "Speak to Shikrik in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3085] = { title = "Hallowed Tablet", description = "Ah, while you were gone a tablet came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the priest trainer Ken'jai. He would have words with you when you're ready.", objectives = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3086] = { title = "Glyphic Tablet", description = "Ah, while you were gone a tablet came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready.", objectives = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3087] = { title = "Etched Parchment", description = "Ah, while you were gone a parchment came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.", objectives = "Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3088] = { title = "Encrypted Parchment", description = "Ah, while you were gone a parchment came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", objectives = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3089] = { title = "Rune-Inscribed Parchment", description = "Ah, while you were gone a parchment came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", objectives = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3090] = { title = "Tainted Parchment", description = "Ah, while you were gone a parchment came for you, $N.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.", objectives = "Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3091] = { title = "Simple Note", description = "Just a moment ago a messenger was looking for you, $N. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading it's contents.", objectives = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3092] = { title = "Etched Note", description = "Just a moment ago a messenger was looking for you, $N. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn't take long in reading it's contents.", objectives = "Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3093] = { title = "Rune-Inscribed Note", description = "Just a moment ago a messenger was looking for you, $N. I believe she was sent by the shaman trainer Meela. If this note is from Meela, I wouldn't take long in reading it's contents.", objectives = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3094] = { title = "Verdant Note", description = "Just a moment ago a messenger was looking for you, $N. I believe she was sent by the druid trainer Gart. If this note is from Gart, I wouldn't take long in reading its contents.", objectives = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3095] = { title = "Simple Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warrior trainer Dannal. I would take some time to read it before heading out again.", objectives = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3096] = { title = "Encrypted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the rogue trainer David Trias. I would take some time to read it before heading out again.", objectives = "Read the Encrypted Scroll and speak to David Trias in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3097] = { title = "Hallowed Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the priest trainer Duesten. I would take some time to read it before heading out again.", objectives = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3098] = { title = "Glyphic Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the mage trainer Isabella. I would take some time to read it before heading out again.", objectives = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3099] = { title = "Tainted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warlock trainer Maximillion. I would take some time to read it before heading out again.", objectives = "Read the Tainted Scroll and speak to Maximillion in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3100] = { title = "Simple Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3101] = { title = "Consecrated Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3102] = { title = "Encrypted Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3103] = { title = "Hallowed Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3104] = { title = "Glyphic Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3105] = { title = "Tainted Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, $N. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3106] = { title = "Simple Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3107] = { title = "Consecrated Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3108] = { title = "Etched Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the hunter trainer Thorgas. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3109] = { title = "Encrypted Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3110] = { title = "Hallowed Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3112] = { title = "Simple Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3113] = { title = "Encrypted Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3114] = { title = "Glyphic Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3115] = { title = "Tainted Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Alamar. Take a gander at it and go find him inside Anvilmar when you've a chance.\n\nAnd watch yerself, $N, your kind ain't too trusted 'round these parts.", objectives = "Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3116] = { title = "Simple Sigil", description = "This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Read the Simple Sigil and speak to Alyissia in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3117] = { title = "Etched Sigil", description = "This sigil was given to me by a messenger from our hunter trainer, Ayanna. It seems Ayanna would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3118] = { title = "Encrypted Sigil", description = "This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3119] = { title = "Hallowed Sigil", description = "This sigil was given to me by a messenger from our priest trainer, Shanda. It seems Shanda would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Read the Hallowed Sigil and speak to Shanda in Aldrassil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3120] = { title = "Verdant Sigil", description = "This sigil was given to me by a messenger from our druid trainer, Mardant. It seems Mardant would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3121] = { title = "A Strange Request", description = "Neeru Fireblade in Orgrimmar has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.\n\nOff with you now -- to Orgrimmar. Here, take this with you. It's a shrunken head that I promised Neeru in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure Neeru will be pleased.\n\nYou'll find Neeru in the Cleft of Shadow.", objectives = "Take the Shrunken Head to Neeru Fireblade in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3122] = { title = "Return to Witch Doctor Uzer'i", description = "Here are the herbs, $N. Take them to Witch Doctor Uzer'i.\n\nPlease let him know that I am satisfied with the shrunken head.", objectives = "Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3123] = { title = "Testing the Vessel", description = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, $N. With it, you will have the power to shrink and capture a creature inside of it.\n\nTravel to the Hinterlands and look for creatures known as Wildkin that were once pets of the night elf goddess Elune. The vicious, primitive, or savage owlbeasts are your targets, $N. Kill 10, and use the muisek vessel to shrink and capture them before their spirits can escape.", objectives = "Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.\n\nBring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3124] = { title = "Hippogryph Muisek", description = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.\n\nHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.\n\nYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here. ", objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3125] = { title = "Faerie Dragon Muisek", description = "$N, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, $N. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3126] = { title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, $N. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3127] = { title = "Mountain Giant Muisek", description = "The last task I will require of you is to travel to the northwest and find the final enemy.\n\nThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", objectives = "Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3128] = { title = "Natural Materials", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.", objectives = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3129] = { title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3130] = { title = "Against the Hatecrest", description = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, $n.  Keep it up.\n\nYou're dismissed.", objectives = "Report to Latronicus Moonspear in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3141] = { title = "Loramus", description = "So you wish to battle demons? You would do well to listen to my tale. ", objectives = "Listen to Loramus Thalipedes tell his story.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3161] = { title = "Gahz'ridian", description = "$N, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins! ", objectives = "Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3181] = { title = "The Horn of the Beast", description = "The gigantic horn has numerous scratches and cracks. An unusual metal object is lodged into the rough surface.\n\nUpon further examination, you notice that the metal is actually a broken axe head. On the metal, the following words are etched:\n\nProperty of Mountaineer Pebblebitty.\n\nWhen you try and dislodge the broken axe head, it shatters into a million pieces.\n\nWoops!", objectives = "Take Margol's Gigantic Horn to Mountaineer Pebblebitty.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3182] = { title = "Proof of Deed", description = "You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.\n\nListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.\n\nGet going! ", objectives = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3201] = { title = "At Last!", description = "I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.\n\nSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.\n\n<Curator Thorius begins to fill out a large document.>\n\nThere we go! You can take that back to Pebblebitty.", objectives = "Take the Proof of Deed back to Mountaineer Pebblebitty.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3221] = { title = "Speak with Renferrel", description = "While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", objectives = "Speak with Apothecary Renferrel at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3261] = { title = "Jorn Skyseer", description = "Your time with me is over, $N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.", objectives = "Speak with Jorn Skyseer at Camp Taurajo.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3281] = { title = "Stolen Silver", description = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.", objectives = "Bring the Stolen Silver to Gazrog in the Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3301] = { title = "Mura Runetotem", description = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.", objectives = "Speak with Mura Runetotem in the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3321] = { title = "Did You Lose This?", description = "You have done much for the Order, $N. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.\n\nWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.", objectives = "Wait for Trenton to finish his work.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3341] = { title = "Bring the End", description = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, $N. An end must come to the Coldbringer.", objectives = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3361] = { title = "A Refugee's Quandary", description = "We drove the troggs out of Gnomeregan, but then it all went so horribly wrong!  Now our home is completely irradiated, and we gnomes have been scattered all over Dun Morogh.\n\nIn my haste to get away from the radiation, I lost all my personal belongings and tools.  It was the trolls that got them.  They stole my chest, my box, and my bucket of bolts!  They took them back to their camps southwest of Anvilmar.\n\nI'm no adventurer - could you find my things and bring them here to me, please?", objectives = "Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3362] = { title = "Thistleshrub Valley", description = "Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, $N.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, $N? Help me out?", objectives = "Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3363] = { title = "Corrupted Songflower", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3364] = { title = "Scalding Mornbrew Delivery", description = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, $N, and don't forget to bring me back my mug!", objectives = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3365] = { title = "Bring Back the Mug", description = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go $N - be a pal and take this empty mug back to Nori for me, would ya now.", objectives = "Return Nori's Mug to Nori Pridedrift.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3367] = { title = "Suntara Stones", description = "<Dorius groans.>\n\nI'm badly injured, $r. Feel... light headed... World spinning... Bleeding... internally.\n\nI must get back to Ironforge. Help me, $N.", objectives = "Help Dorius get back to Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3368] = { title = "Suntara Stones", description = "Brother,\n\nIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.\n\nAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.\n\nHelp them, brother. It is the final wish of a dead man.\n\n-Dorius", objectives = "Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3369] = { title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more. ", objectives = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3370] = { title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, $N, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... \n\nMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.", objectives = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3371] = { title = "Dwarven Justice", description = "There is an empty, vacuous hole, where my heart used to be, $N. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men.", objectives = "Return to the Searing Gorge and find Dorius's archaeology unit. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3372] = { title = "Release Them", description = "Release them, $r. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.\n\nThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.\n\n<The dying archaeologist collapses.>", objectives = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3373] = { title = "The Essence of Eranikus", description = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"", objectives = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3374] = { title = "The Essence of Eranikus", description = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.\n\n\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"\n\n\"Do this $N, and we will work together to redeem a soul worthy of redemption.\"", objectives = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3375] = { title = "Replacement Phial", description = "Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, $r.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!\n\nin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.", objectives = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3376] = { title = "Break Sharptusk!", description = "$N - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.\n\nWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!\n\nHe will be found in the ravine to the east in their makeshift village.", objectives = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3377] = { title = "Prayer to Elune", description = "Will you assist me, mortal? Hear my tale.", objectives = "Hear Zamael tell his tale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3378] = { title = "Prayer to Elune", description = "Will you assist me, mortal? Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person.\n\nIf you do recover my prayer, take it to Astarii Starseeker in Darnassus. It matters little that my faith has been rekindled after the countless malevolent actions that I have taken against this world and its inhabitants, but my prayer must be heard. Absolution is the last thing I expect.", objectives = "Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3379] = { title = "Shadoweaver", description = "The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade.\n\nRecently, a group of poachers has encroached upon these lands, carelessly slaying spiders en masse without so much as a thought as to the long term effect of their actions. The first task I ask of you, then, is a simple one: Find them... and end them.\n\nBegin your search to the north.\n\nIf you require assistance, speak with Raze.", objectives = "Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3380] = { title = "The Sunken Temple", description = "There are restless spirits in this world, $N. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.", objectives = "Find Marvon Rivetseeker in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3382] = { title = "A Crew Under Fire", description = "We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!\n\nI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.\n\nI'm sorry you've come along now, $N, but it's out of my hands.\n\nAre you ready for the fight of your life?", objectives = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3385] = { title = "The Undermarket", description = "They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.\n\nIt gets worse, $N. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.\n\nWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.\n\nTo the Cauldron!", objectives = "Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3402] = { title = "The Undermarket", description = "I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.", objectives = "Speak with Vizzklick in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3421] = { title = "Return Trip", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3441] = { title = "Divine Retribution", description = "Hear my tale, adventurer.", objectives = "Listen as Kalaran Windblade tells his story.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3442] = { title = "The Flawless Flame", description = "You have made the right decision, $N.\n\nWe must strike where we will do the most damage: the four sentry towers.\n\nWith the four towers in flames, we can initiate an offensive before they have time to react.\n\nYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.\n\nBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.\n\nThe golems and elementals in these lands should be your first target.", objectives = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3443] = { title = "Forging the Shaft", description = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.", objectives = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3444] = { title = "The Stone Circle", description = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.", objectives = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3445] = { title = "The Sunken Temple", description = "I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.", objectives = "Find Marvon Rivetseeker in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3446] = { title = "Into the Depths", description = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.", objectives = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3447] = { title = "Secret of the Circle", description = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, $N. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", objectives = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3448] = { title = "Passing the Burden", description = "I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.", objectives = "Speak to Tymor in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3449] = { title = "Arcane Runes", description = "Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.", objectives = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3450] = { title = "An Easy Pickup", description = "I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.", objectives = "Speak to Xiggs Fuselighter in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3451] = { title = "Signal for Pickup", description = "Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.", objectives = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3452] = { title = "The Flame's Casing", description = "We need one final piece to form the torch.\n\nIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.", objectives = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3453] = { title = "The Torch of Retribution", description = "Give me a moment to combine the pieces and apply the necessary enchantments.", objectives = "Wait for Kalaran Windblade to complete the Torch of Retribution.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3454] = { title = "The Torch of Retribution", description = "The torch must now be bound to its owner. Pick up the torch, $N. ", objectives = "Take the Torch of Retribution.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3461] = { title = "Return to Tymor", description = "Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.\n\nThanks again for helping him out though, and good luck.\n\nOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?", objectives = "Return Tymor's Drawing Kit to him in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3462] = { title = "Squire Maltrake", description = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.", objectives = "Speak with Squire Maltrake.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3463] = { title = "Set Them Ablaze!", description = "Listen well, $N. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the Torch of Retribution within their fortifications. Beware the elite sentry units of the Dark Irons, $N.", objectives = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3481] = { title = "Trinkets...", description = "The chest appears locked.", objectives = "Open the chest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3483] = { title = "Signal for Pickup", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3501] = { title = "Everything Counts In Large Amounts", description = "Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.\n\nWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.\n\nReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3502] = { title = "One Draenei's Junk...", description = "Well, after that display of voracious greed, I feel nauseous.\n\nRegardless, I shall not dwell too long on your material addiction.\n\nFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3503] = { title = "Meeting with the Master", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3504] = { title = "Betrayed", description = "Betraying, thieving woman! That's what I call her--that's all she'll ever be!\n\nI may have made a grave mistake, $N. I trusted a blood elf. What's worse, I trusted a woman!\n\nShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.\n\nI want vengeance, $N, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.", objectives = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3505] = { title = "Betrayed", description = "I thought as much.\n\nWe start our crusade against her workers along the southern bluffs on the northern peninsula of Azshara. Kill them with bloody rage--let them know they've betrayed the wrong allies.\n\nDo not concern yourself with her yet--she spends most of her time with her bodyguards searching Azshara. It would be prudent after you've slain her workers to find her personal camp. Scouting out where we can attack her would be wise. Perhaps there is something there we can use to provoke her.", objectives = "Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3506] = { title = "Betrayed", description = "A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?\n\nYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.\n\nYou close the book and begin to decide which crystal to destroy. ", objectives = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3507] = { title = "Betrayed", description = "Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly.\n\nAh, this is indeed a good day. Thank you for your help, $N.", objectives = "Speak to Belgrom Rockmaul in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3508] = { title = "Breaking the Ward", description = "You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.\n\nTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.\n\nBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.", objectives = "Wait for Loramus to complete the enlightenment spell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3509] = { title = "The Name of the Beast", description = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information. ", objectives = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3510] = { title = "The Name of the Beast", description = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.\n\nFor that, you will be given the name that you seek and something else of equal importance.\n\nShe roams the clutch... Hetaera she is called.\n\n<Lord Arkkoroc points to the southwest.>\n\nGo!", objectives = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3511] = { title = "The Name of the Beast", description = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.\n\nThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.\n\n<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>\n\nTake the temper back to Loramus along with the name of the beast: Rakh'likh.", objectives = "Take the temper back to Loramus Thalipedes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3512] = { title = "In Eranikus' Own Words", description = "$N, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.", objectives = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3513] = { title = "The Runed Scroll", description = "The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?\n\nThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.", objectives = "Take the Runed Scroll to the northern guard tower in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3514] = { title = "Horde Presence", description = "This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.\n\nShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.\n\n$N, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, $N. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.", objectives = "Kill the leader of the Talon Den, Rynthariel the Keymaster.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3517] = { title = "Stealing Knowledge", description = "I admit, $N, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.\n\nBefore I left, I did some research and you would be surprised how many valuable items are lying around.\n\nI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.\n\nThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.", objectives = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3518] = { title = "Delivery to Magatha", description = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.\n\nBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.", objectives = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3519] = { title = "A Friend in Need", description = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", objectives = "Speak to Dirania Silvershine in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3520] = { title = "Screecher Spirits", description = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.", objectives = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3521] = { title = "Iverron's Antidote", description = "We may be able to help Iverron, as I know of an antidote that should help with the poison. It requires some ingredients, though, before I can make it.\n\nI'll need Hyacinth mushrooms. You can find these growing under trees, or you may collect them from the grell south of here; they seem to have taken a liking to them. I'll also need Moonpetal lilies, which only grow around watery pools.\n\nThe last ingredient may prove the most difficult. From the very spiders that poisoned Iverron, collect Webwood ichor.", objectives = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3522] = { title = "Iverron's Antidote", description = "The antidote is ready, $N. Please see that Iverron drinks it.\n\nThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.\n\nSpeed be with you, $N.", objectives = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3523] = { title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.", objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3524] = { title = "Washed Ashore", description = "Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.\n\nThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?", objectives = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3525] = { title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.\n\nAre you with me?!", objectives = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3526] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3527] = { title = "The Prophecy of Mosh'aru", description = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me.", objectives = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3528] = { title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the egg of Hakkar.", objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3541] = { title = "Delivery to Jes'rimon", description = "I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.\n\nDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.\n\nHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.", objectives = "Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3542] = { title = "Delivery to Andron Gant", description = "Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.\n\nHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.\n\nTake the Tablet of Markri and return to me for your part of the reward.", objectives = "Bring the Tablet of Markri to Andron Gant in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3561] = { title = "Delivery to Archmage Xylem", description = "This final tablet goes to someone very dangerous, $N. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.\n\nArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.\n\nHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.", objectives = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3562] = { title = "Magatha's Payment to Jediga", description = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.\n\nGo swiftly, $N. Tell your master I will be awaiting her here.", objectives = "Deliver Magatha's Note to Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3563] = { title = "Jes'rimon's Payment to Jediga", description = "Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.\n\nYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.\n\nTell her that, and maybe in the future I have need of your services again, $N.", objectives = "Deliver Jes'rimon's Note to Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3564] = { title = "Andron's Payment to Jediga", description = "Here... take... <hic> this to Jediga. Good luck to ya!", objectives = "Deliver Andron's Note to Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3565] = { title = "Xylem's Payment to Jediga", description = "What is it? Oh yes, your payment. Of course.\n\nTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.", objectives = "Deliver Xylem's Note to Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3566] = { title = "Rise, Obsidion!", description = "It... It... It was all a trap.\n\nForgive... me.\n\nKill the bastard... Kill him for us... for Thorius.", objectives = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3567] = { title = "To the Top", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3568] = { title = "Seeping Corruption", description = "See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.\n\nAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.\n\nI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.", objectives = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3569] = { title = "Seeping Corruption", description = "Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.", objectives = "Give Cuely's Elixir to Thersa Windsong in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3570] = { title = "Seeping Corruption", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3601] = { title = "Kim'jael Indeed!", description = "Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, $N? Little rat... or something like that. The big bullies!\n\nThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!\n\nGoes to show you, you can't trust a Blood elf.\n\nThe problem is, they still have my equipment and I can't get it back. Help me out?", objectives = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3602] = { title = "Azsharite", description = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.\n\nThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.\n\nYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.", objectives = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.\n\nReturn to Loramus when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3621] = { title = "The Formation of Felbane", description = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.\n\nIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.\n\nMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.", objectives = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3625] = { title = "Enchanted Azsharite Fel Weaponry", description = "$N, the creation of each weapon will take some time.\n\nAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!\n\nNow give me a moment to craft your weapon, $N.", objectives = "Wait for Galvan to finish forging the weaponry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3626] = { title = "Return to the Blasted Lands", description = "The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.", objectives = "Return to the Fallen Hero of the Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3627] = { title = "Uniting the Shattered Amulet", description = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.\n\nGo $N! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!", objectives = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.\n\nRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3628] = { title = "You Are Rakh'likh, Demon", description = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.\n\nShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.", objectives = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3629] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3630] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3631] = { title = "Summon Felsteed", description = "Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.", objectives = "Speak to Strahad Farsan in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3632] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n$N, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3633] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n$N, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3634] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.\n\n$N, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3635] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3636] = { title = "Bring the Light", description = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, $N.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, $N; put an end to this evil union.", objectives = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3637] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n$N, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3638] = { title = "The Pledge of Secrecy", description = "Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.\n\nIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.", objectives = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3639] = { title = "Show Your Work", description = "As your mentor, I want samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is analyze them for ways to emphasize goblin-oriented techniques in your future efforts.  I need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!\n\nSubmit these items to me and I will issue you your own Goblin Engineer Membership Card; it is required for access to all goblin engineering trainers!", objectives = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3640] = { title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3641] = { title = "Show Your Work", description = "As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3642] = { title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, $N.", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3643] = { title = "Show Your Work", description = "As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, $N.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3644] = { title = "Membership Card Renewal", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3645] = { title = "Membership Card Renewal", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3646] = { title = "Membership Card Renewal", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3647] = { title = "Membership Card Renewal", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3661] = { title = "Favored of Elune?", description = "Wildkin are quite unpredictable creatures, $N. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?", objectives = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3681] = { title = "Tome of Divinity", description = "Sorry to interrupt your travels, $r, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.", objectives = "Speak with Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3701] = { title = "The Smoldering Ruins of Thaurissan", description = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.", objectives = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3702] = { title = "The Smoldering Ruins of Thaurissan", description = "Would you like to hear a brief history of the Dark Iron dwarves?", objectives = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3721] = { title = "An OOX of Your Own", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3741] = { title = "Hilary's Necklace", description = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", objectives = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3761] = { title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.\n\nThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!", objectives = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3762] = { title = "Assisting Arch Druid Runetotem", description = "Excuse me $c, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3763] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me $c, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3764] = { title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.\n\nYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.", objectives = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3765] = { title = "The Corruption Abroad", description = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned $c such as yourself.", objectives = "Travel to Gershala Nightwhisper in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3781] = { title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.\n\nTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.", objectives = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3782] = { title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.\n\nTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.", objectives = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3783] = { title = "Are We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.", objectives = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3784] = { title = "Assisting Arch Druid Runetotem", description = "Excuse me $c, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3785] = { title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3786] = { title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3787] = { title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3788] = { title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3789] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me $c, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3790] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me $c, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3791] = { title = "The Mystery of Morrowgrain", description = "Let me to be frank with you, $N.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.\n\nI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.", objectives = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3792] = { title = "Morrowgrain to Feathermoon Stronghold", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3801] = { title = "Dark Iron Legacy", description = "Greetings, $N. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", objectives = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3802] = { title = "Dark Iron Legacy", description = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.", objectives = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3803] = { title = "Morrowgrain to Darnassus", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3804] = { title = "Morrowgrain to Thunder Bluff", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3821] = { title = "Dreadmaul Rock", description = "Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, $N, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.", objectives = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3822] = { title = "Krom'Grul", description = "My whole platoon was captured, $N. All were slain - except me.\n\nTheir leader, Krom'Grul, wanted to save me for some sort of ritual.\n\nI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!\n\nFind Krom'Grul and kill him! Take my ring back to Thal'trak.\n\nAnd $N, tell him that we will meet again... in another life. ", objectives = "Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3823] = { title = "Extinguish the Firegut", description = "We must strike at our enemies before they strike at us!\n\nI'll make this brief, soldier.\n\nThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.\n\nLeave your mark, $N. Cripple their forces and return to me when the job is done.\n\n<Oralius grabs at the air and makes a choking motion.>\n\nI WILL KILL YOU, WINKY!", objectives = "Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3824] = { title = "Gor'tesh the Brute Lord", description = "They're reeling I tell you! Our next strike must be decisive.\n\nThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.\n\nBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.\n\nYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.\n\nSHUT UP, WINKY!", objectives = "Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3825] = { title = "Ogre Head On A Stick = Party", description = "Just one last thing you must do, soldier.\n\nI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.\n\n<Oralius seems to be losing touch with reality.>", objectives = "Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3841] = { title = "An Orphan Looking For a Home", description = "Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus?\n\nWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.\n\nSay, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say?\n\nIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.", objectives = "Speak to Quentin in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3842] = { title = "A Short Incubation", description = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.\n\nSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.\n\nI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.", objectives = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3843] = { title = "The Newest Member of the Family", description = "A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed!\n\nThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.\n\nBut hurry, $N, this egg is fragile and will not last long without proper care.", objectives = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3844] = { title = "It's a Secret to Everybody", description = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...", objectives = "Look around in the pond for a clue about who this wrecked raft may belong to.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3845] = { title = "It's a Secret to Everybody", description = " Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.\n\nThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.", objectives = "Examine the items inside the pack and bring them to their owner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3861] = { title = "CLUCK!", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", objectives = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3881] = { title = "Expedition Salvation", description = "I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!\n\nAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?", objectives = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3882] = { title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", objectives = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3883] = { title = "Alien Ecology", description = "Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.\n\nIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!", objectives = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns.\n\nBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3884] = { title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.", objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3901] = { title = "Rattling the Rattlecages", description = "You've shown your potential to the Forsaken under normal circumstances $N - now let's see you under pressure.\n\nThe Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.", objectives = "Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3902] = { title = "Scavenging Deathknell", description = "You there!  If you're looking for something to make yourself useful, then listen up!\n\nWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!\n\nWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.", objectives = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3903] = { title = "Milly Osworth", description = "You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh?\n\nI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.", objectives = "Speak with Milly Osworth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3904] = { title = "Milly's Harvest", description = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.\n\nPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.\n\nBring me those crates!  Save my harvest!", objectives = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3905] = { title = "Grape Manifest", description = "Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.\n\nYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.", objectives = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3906] = { title = "Disharmony of Flame", description = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.\n\nTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.\n\nEnd the disruption and return to me.", objectives = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3907] = { title = "Disharmony of Fire", description = "I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness.\n\nThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.\n\nFind him and discover where his master hides. Return to me when you have collected this information.", objectives = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3908] = { title = "It's a Secret to Everybody", description = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...\n\nThese items you brought to me, though... I am remembering something.\n\nMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!\n\nAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.", objectives = "Take Linken's Sword to Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3909] = { title = "The Videre Elixir", description = "Now, what's this? Linken... FORGOT?\n\nOh, I see... Lost his memory...\n\nWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.\n\nListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.", objectives = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3912] = { title = "Meet at the Grave", description = "This elixir will allow you to speak with one that you would not normally even see...\n\nTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.\n\nIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.\n\nRemember, he will only speak to you in that form...", objectives = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3913] = { title = "A Grave Situation", description = "If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.\n\nPush on the stone, and you will learn of these secrets...", objectives = "Resurrect, then look for the gravestone that Gaeriyan told you to find.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3914] = { title = "Linken's Sword", description = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!", objectives = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3921] = { title = "Wenikee Boltbucket", description = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!\n\nTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.", objectives = "Bring the Broken Samophlange to Wenikee Boltbucket.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3922] = { title = "Nugget Slugs", description = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.", objectives = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3923] = { title = "Rilli Greasygob", description = "Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.\n\nYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.\n\nYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.", objectives = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3924] = { title = "Samophlange Manual", description = "I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...\n\nBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.", objectives = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3941] = { title = "A Gnome's Assistance", description = "Thinking... Thinking... I know I came here for something important...\n\nI have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.\n\nWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!", objectives = "Find J.D. Collie in the cave at Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3942] = { title = "Linken's Memory", description = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.\n\nSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?\n\nI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?", objectives = "Find Eridan Bluewind in southern Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3961] = { title = "Linken's Adventure", description = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.\n\nBring the totem to him. See if that helps him remember why he came here.", objectives = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3962] = { title = "It's Dangerous to Go Alone", description = "$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.\n\nBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.\n\nBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.\n\nYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice.", objectives = "Travel to Fire Plume Ridge, south of Marshal's Refuge.\n\nFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[3981] = { title = "Commander Gor'shak", description = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...\n\n<Galamav grimaces.>\n\nWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.\n\nIf he's still alive in the Depths, you'll have to find him.\n\nA trap you say? Well no kidding, numb hooves! That's why you're going!", objectives = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
